<template><section class="position-evidence" aria-label="仓位纪律依据"><h3>仓位纪律依据</h3><p>{{ evidence.scope }}</p><p v-if="evidence.status==='refresh_required'">日期已变化，请重新载入仓位与纪律依据。</p><template v-else><p v-if="evidence.status==='not_held'">当前没有此标的持仓，不生成仓位纪律警示。</p><p v-else>组合持仓占比：{{ evidence.weight_percent===null?'待补':money(evidence.weight_percent)+'%' }} · {{ evidence.constitution_evidence?'已保存纪律 v'+evidence.constitution_evidence.revision:'尚未保存纪律' }}</p><article v-for="signal in evidence.signals" :key="signal.code"><strong>{{ signal.title }}</strong><p>{{ money(signal.current_percent) }}% / 阈值 {{ signal.limit_percent }}%</p><p>{{ signal.next_step }}</p></article><section v-if="evidence.context_signals?.length"><h4>成本与事件提示</h4><article v-for="signal in evidence.context_signals" :key="signal.code"><strong>{{ signal.title }}</strong><p>{{ signal.detail }}</p><p>{{ signal.next_step }}</p></article></section><p v-if="evidence.status==='ready'&&!evidence.signals.length">未触及已保存的仓位观察/上限阈值。</p><ul v-if="evidence.missing.length"><li v-for="gap in evidence.missing" :key="gap">{{ gap }}</li></ul></template><p>{{ evidence.notice }}</p><details><summary>核对仓位、汇率与纪律来源</summary><pre>{{ evidence }}</pre></details></section></template>
